<script setup lang="ts">
import TdBrand from '../../Taildash/components/TdBrand.vue'
import { computed, nextTick, onBeforeUnmount, onMounted, shallowRef, useTemplateRef, watch } from 'vue'
import { Head, router, useForm } from '@inertiajs/vue3'
import { CheckCircleIcon, XCircleIcon, PaperClipIcon, InformationCircleIcon } from '@heroicons/vue/24/outline'
import StatusBadge from '../../Components/StatusBadge.vue'
import FormErrorSummary from '../../Components/FormErrorSummary.vue'
import DataState from '../../Components/DataState.vue'
import TailAdminTable from '../../TailAdminSource/components/ui/table/Table.vue'
import { formatDateBR } from '../../utils/dateDisplay'
import { formatDateTimeBR } from '../../utils/dateDisplay'
type PublicState = 'valid' | 'viewed' | 'sent' | 'expired' | 'revoked' | 'invalid' | 'error' | 'approved' | 'rejected' | 'rate_limited'
type PublicActions = { approve?: string | null; reject?: string | null }
type PublicAttachment = { id?: string | number; name?: string; original_name?: string; url?: string | null; download_url?: string | null; href?: string | null; mime_type?: string | null; size?: number | null; size_bytes?: number | null; size_human?: string | null; created_at?: string | null }
const props = withDefaults(defineProps<{ quote?: any; state?: PublicState; token?: string; actions?: PublicActions; retry_after_seconds?: number | string | null; retry_after?: number | string | null; retryAfter?: number | string | null; contact?: string | null; contact_url?: string | null; 'Retry-After'?: number | string | null }>(), { state: 'valid', actions: () => ({}) })
const form = useForm({ name: '' }); const confirmingDecision = shallowRef<'approve' | 'reject' | null>(null); const statusMessage = shallowRef(''); const retrying = shallowRef(false); const previousFocus = shallowRef<HTMLElement | null>(null)
const dialog = useTemplateRef<HTMLDivElement>('decisionDialog'); const mainContent = useTemplateRef<HTMLDivElement>('publicQuoteContent')
const publicState = computed<PublicState>(() => (props.state === 'valid' && props.quote?.status === 'draft' ? 'valid' : props.state === 'valid' ? props.quote?.status || 'valid' : props.state) as PublicState)
const routeBase = computed(() => { if (props.token) return `/public/quotes/${encodeURIComponent(props.token)}`; const match = window.location.pathname.match(/^\/public\/quotes\/[^/]+/); return match?.[0] || null })
const actionUrl = (decision: 'approve' | 'reject') => props.actions?.[decision] || (routeBase.value ? `${routeBase.value}/${decision}` : null)
const isRenderable = computed(() => Boolean(props.quote) && ['valid', 'viewed', 'sent', 'approved', 'rejected'].includes(publicState.value))
const canDecide = computed(() => isRenderable.value && Boolean(actionUrl('approve')) && Boolean(actionUrl('reject')) && !['approved', 'rejected'].includes(props.quote?.status))
const retryAfterSeconds = computed(() => { const raw = props.retry_after_seconds ?? props.retry_after ?? props.retryAfter ?? props['Retry-After']; const value = Number(raw); return Number.isFinite(value) && value > 0 ? Math.ceil(value) : null })
const retryRemaining = shallowRef(0); let retryTimer: ReturnType<typeof setInterval> | undefined
const retryAfterLabel = computed(() => { const seconds = retryRemaining.value; if (!seconds) return 'Você pode tentar novamente agora.'; if (seconds < 60) return `Aguarde ${seconds} segundo${seconds === 1 ? '' : 's'} antes de tentar novamente.`; const minutes = Math.ceil(seconds / 60); return `Aguarde cerca de ${minutes} minuto${minutes === 1 ? '' : 's'} antes de tentar novamente.` })
const canRetryPublic = computed(() => ['invalid', 'error'].includes(publicState.value) || (publicState.value === 'rate_limited' && retryRemaining.value === 0))
const stateCopy = computed(() => ({ approved: ['Orçamento aprovado', 'Esta decisão já foi registrada com sucesso.', 'success'], rejected: ['Orçamento recusado', 'Esta decisão já foi registrada.', 'neutral'], expired: ['Este link expirou', 'Peça ao prestador um novo link para continuar.', 'warning'], revoked: ['Este link foi revogado', 'Peça ao prestador um novo link para continuar.', 'warning'], invalid: ['Orçamento indisponível', 'O link não é válido ou o conteúdo não está mais disponível. Tente novamente; se continuar inválido, peça ao prestador um novo link.', 'error'], error: ['Não foi possível abrir o orçamento', 'Tente novamente ou peça ao prestador um novo link.', 'error'], rate_limited: ['Muitas tentativas', retryAfterLabel.value, 'warning'], valid: ['', '', 'neutral'], viewed: ['', '', 'neutral'], sent: ['', '', 'neutral'] }[publicState.value] || ['Não foi possível abrir o orçamento.', 'Tente novamente.', 'error']))
const attachments = computed(() => (props.quote?.attachments || []) as PublicAttachment[])
const money = (cents?: number | null) => cents == null ? '—' : `R$ ${(cents / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
const attachmentUrl = (a: PublicAttachment) => a.url || a.download_url || a.href || null
const attachmentSize = (a: PublicAttachment) => a.size_human || ((a.size ?? a.size_bytes) == null ? null : `${Math.ceil(Number(a.size ?? a.size_bytes) / 1024)} KB`)
const focusable = () => Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])') || [])
function modalKeydown(event: KeyboardEvent) { if (!confirmingDecision.value) return; if (event.key === 'Escape') { event.preventDefault(); cancelDecision(); return } if (event.key !== 'Tab') return; const controls = focusable(); if (!controls.length) return; const first = controls[0]; const last = controls[controls.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() } }
function openModal(decision: 'approve' | 'reject') { if (!canDecide.value || !form.name.trim()) return; previousFocus.value = document.activeElement as HTMLElement; confirmingDecision.value = decision; document.body.style.overflow = 'hidden'; if (mainContent.value) mainContent.value.inert = true; nextTick(() => focusable()[0]?.focus()) }
function cancelDecision(force = false) { if (form.processing && !force) return; confirmingDecision.value = null; document.body.style.overflow = ''; if (mainContent.value) mainContent.value.inert = false; nextTick(() => previousFocus.value?.focus()) }
function decide() { const decision = confirmingDecision.value; const url = decision ? actionUrl(decision) : null; if (!decision || !url) return; statusMessage.value = decision === 'approve' ? 'Enviando aprovação…' : 'Enviando recusa…'; form.post(url, { preserveScroll: true, onError: () => { statusMessage.value = 'Não foi possível registrar a decisão. Revise os dados e tente novamente.'; cancelDecision(true) }, onSuccess: () => cancelDecision(true) }) }
function syncRetryCooldown() { if (retryTimer) clearInterval(retryTimer); retryRemaining.value = publicState.value === 'rate_limited' ? (retryAfterSeconds.value || 0) : 0; if (retryRemaining.value > 0) retryTimer = setInterval(() => { retryRemaining.value = Math.max(0, retryRemaining.value - 1); if (!retryRemaining.value && retryTimer) { clearInterval(retryTimer); retryTimer = undefined } }, 1000) }
function retryPublicQuote() { if (!canRetryPublic.value || retrying.value) return; retrying.value = true; statusMessage.value = 'Tentando abrir o orçamento novamente…'; router.reload({ preserveScroll: true, onError: () => { retrying.value = false; statusMessage.value = 'Não foi possível tentar novamente. Verifique a conexão e tente de novo.' }, onFinish: () => { retrying.value = false } }) }
watch([retryAfterSeconds, publicState], syncRetryCooldown, { immediate: true })
onMounted(() => window.addEventListener('keydown', modalKeydown)); onBeforeUnmount(() => { window.removeEventListener('keydown', modalKeydown); if (retryTimer) clearInterval(retryTimer); document.body.style.overflow = ''; if (mainContent.value) mainContent.value.inert = false })
</script>
