        <div class="state-panel__icon flex size-14 items-center justify-center rounded-full bg-td-icon text-td-primary [&_svg]:size-7"><CheckCircleIcon class="size-5 shrink-0" v-if="stateCopy[2] === 'success'" aria-hidden="true" /><InformationCircleIcon class="size-5 shrink-0" v-else aria-hidden="true" /></div>
        <h1 id="public-quote-title">{{ stateCopy[0] }}</h1><p>{{ stateCopy[1] }}</p>
        <div class="state-actions flex flex-col items-center gap-4 sm:flex-row sm:flex-wrap sm:justify-center"><button v-if="['invalid','error','rate_limited'].includes(publicState)" class="btn-primary inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-center text-sm font-medium leading-5 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none [&_svg]:size-5 [&_svg]:shrink-0 border border-td-primary bg-td-primary text-white hover:bg-td-primary/90" type="button" :disabled="retrying || !canRetryPublic" :aria-busy="retrying" @click="retryPublicQuote">{{ retrying ? 'Tentando…' : retryRemaining ? `Tentar novamente em ${retryAfterLabel.replace('Aguarde ', '')}` : 'Tentar novamente' }}</button><a v-if="props.contact_url" class="btn-secondary inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-center text-sm font-medium leading-5 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none [&_svg]:size-5 [&_svg]:shrink-0 border border-td-border bg-white text-td-ink hover:border-td-primary hover:text-td-primary" :href="props.contact_url">Falar com o prestador</a><span v-else-if="['invalid','error','expired','revoked'].includes(publicState)">Peça ao prestador um novo link ou orientação para continuar.</span></div>
