        <p v-if="props.quote.description">{{ props.quote.description }}</p><div v-if="props.quote.items?.length" class="quote-items-wrap min-w-0 max-w-full overflow-x-auto rounded-xl border border-gray-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary" tabindex="0" role="region" aria-label="Itens do orçamento, tabela com rolagem horizontal"><p class="px-3 pt-3 text-sm text-td-body sm:hidden">Deslize para consultar todos os itens.</p><TailAdminTable class="quote-items w-full min-w-[32rem] border-collapse text-left text-sm leading-5 [&_th]:border-b [&_th]:border-gray-100 [&_th]:bg-white [&_th]:px-5 [&_th]:py-3 [&_th]:text-xs [&_th]:font-medium [&_th]:text-gray-500 [&_td]:border-b [&_td]:border-gray-100 [&_td]:px-3 [&_td]:py-4 [&_td]:align-top [&_td]:text-td-body"><caption class="sr-only">Itens do orçamento. Em telas estreitas, deslize horizontalmente para consultar todas as colunas.</caption><thead><tr><th>Item</th><th>Qtd.</th><th>Valor</th></tr></thead><tbody><tr v-for="item in props.quote.items" :key="item.id"><td>{{ item.description }}</td><td>{{ item.quantity }} {{ item.unit }}</td><td>{{ money(item.subtotal_cents) }}</td></tr></tbody></TailAdminTable></div><DataState v-else kind="empty" title="Nenhum item informado" /><div class="quote-total flex flex-wrap items-center justify-between gap-4 border-t border-td-border py-5 text-base [&_strong]:text-2xl [&_strong]:font-bold [&_strong]:leading-[30px] [&_strong]:text-td-ink"><span>Total</span><strong>{{ money(props.quote.total_cents) }}</strong></div>
