çamento'" loading="lazy" /><video v-else-if="attachment.mime_type?.startsWith('video/') && attachmentUrl(attachment)" class="max-h-80 w-full rounded-lg bg-black" :src="attachmentUrl(attachment) || undefined" controls preload="metadata">Seu navegador não suporta vídeo.</video></li></ul></section>
        <section v-if="props.quote.history?.length" class="rounded-xl border border-gray-200 bg-white p-4 sm:p-6" aria-labelledby="public-history-title">
